// Settings come from the summers.datastore.config.keys data table: { CATEGORY: { key: value } }.
const parse = v => {
  if (v === null || v === undefined) return null;
  const s = String(v).trim();
  if (/^(true|false)$/i.test(s)) return s.toLowerCase() === 'true';
  if (/^-?\d+(\.\d+)?$/.test(s)) return Number(s);
  if (/^[\[{]/.test(s)) { try { return JSON.parse(s); } catch (e) { /* keep as text */ } }
  return s;
};
const cfg = {};
for (const { json: r } of $input.all()) {
  if (!r || !r.category || !r.key) continue;
  (cfg[r.category] ||= {})[r.key] = parse(r.value);
}
// Fail loudly if a required setting is missing, rather than running with a guess.
const REQUIRED = ["INV_PROC_CONFIG.validation_tolerance", "INV_PROC_CONFIG.indirect_require_confirmed_map", "INV_PROC_CONFIG.indirect_amount_basis"];
const missing = REQUIRED.filter(p => { const [c, k] = p.split('.'); const v = cfg[c]?.[k]; return v === undefined || v === null || v === ''; });
if (missing.length) throw new Error('Missing settings in summers.datastore.config.keys: ' + missing.join(', '));
return [{ json: { cfg } }];

const LEGAL_SUFFIXES = /\b(incorporated|llc|l\.l\.c|inc|corp|corporation|co|company|ltd|limited|llp|lp|enterprises?|facilit(?:y|ies)|industries|international|the)\b/g;
function normVendor(raw) {
  if (!raw) return '';
  return String(raw).toLowerCase().replace(/&/g, ' and ').replace(/[.,\/#!$%\^*;:{}=\-_`~()'"]/g, ' ')
    .replace(LEGAL_SUFFIXES, ' ').replace(/\s+/g, ' ').trim();
}

// Non-PO invoice -> Vendor_Account_Map row -> GL, department, Sage vendor and location (via Location_Master).
const I = $('Build Config').first().json.cfg.INV_PROC_CONFIG;
const CONFIG = {
  TOL: I.validation_tolerance,
  REQUIRE_CONFIRMED: I.indirect_require_confirmed_map === true,
  AMOUNT_BASIS: I.indirect_amount_basis,   // 'current_charges' (current period only) or 'invoice_total'
  MAP: { account: 'account_number', vendor: 'vendor_name', code: 'location_code', entity: 'sage_entity_id',
         gl: 'gl_account', department: 'department_code', sageVendor: 'sage_vendor_id', confirmed: 'confirmed_by_client' },
  LOC: { code: 'location_code', aliases: 'code_aliases', active: 'active', entity: 'sage_entity_id',
         sageLocation: 'sage_location_id', name: 'location_name', tenant: 'st_tenant_id' },
};
const M = CONFIG.MAP, LC = CONFIG.LOC;
const ctx = JSON.parse(JSON.stringify($('Start').first().json));
ctx.warnings = ctx.warnings || [];
const inv = ctx.invoice;
const exc = (s, r) => { ctx.status = s; ctx.reason = r; return [{ json: ctx }]; };
const up = v => String(v ?? '').trim().toUpperCase();
const lc = v => String(v ?? '').trim().toLowerCase();
const round2 = n => Math.round(n * 100) / 100;
const normAcct = v => String(v ?? '').replace(/[^A-Za-z0-9]/g, '').replace(/^0+/, '').toUpperCase();
const vendorLike = name => { const a = normVendor(name), b = normVendor(ctx.vendor?.name); return a && b && (a === b || a.includes(b) || b.includes(a)); };

const clean = rows => rows.map(i => i.json).filter(r => r && Object.keys(r).length && !r.error);
const mapRows = clean($('Load Vendor Account Map').all());
const locRows = clean($('Load Location Master').all());

// 1. Find the account
const acct = normAcct(inv.account_number || ctx.customer?.account);
let hits = acct ? mapRows.filter(r => normAcct(r[M.account]) === acct) : mapRows.filter(r => vendorLike(r[M.vendor]));
if (hits.length > 1) { const v = hits.filter(r => vendorLike(r[M.vendor])); if (v.length) hits = v; }
if (hits.length > 1 && ctx.location?.status === 'RESOLVED') { const l = hits.filter(r => up(r[M.code]) === up(ctx.location.code)); if (l.length) hits = l; }
if (!hits.length) return exc('ACCOUNT_NOT_MAPPED', `${ctx.vendor?.name ?? 'Vendor'} account ${acct || '(none printed)'} is not in Vendor_Account_Map and the invoice has no PO. If this is a supplier invoice, it needs a ServiceTitan PO; if it is an indirect expense, add the account to Vendor_Account_Map`);
if (hits.length > 1) return exc('ACCOUNT_AMBIGUOUS', `${hits.length} Vendor_Account_Map rows match ${ctx.vendor?.name} ${acct || ''}`.trim());
const row = hits[0];
if (acct && !vendorLike(row[M.vendor])) ctx.warnings.push(`Account ${acct} is mapped to "${row[M.vendor]}" but the invoice vendor is "${ctx.vendor?.name}"`);
if (row[M.confirmed] !== true) {
  if (CONFIG.REQUIRE_CONFIRMED) return exc('MAPPING_NOT_CONFIRMED', `Vendor_Account_Map row for ${row[M.vendor]} ${row[M.account]} is not confirmed by the client`);
  ctx.warnings.push(`Vendor_Account_Map row for ${row[M.vendor]} ${row[M.account]} is not client-confirmed`);
}

// 2. GL and department
const glRaw = String(row[M.gl] ?? '').trim();
const gl = (glRaw.match(/^\s*([\w.]+)/) || [])[1] || null;
if (!gl) return exc('GL_NOT_MAPPED', `No GL account for ${row[M.vendor]} ${row[M.account]} in Vendor_Account_Map`);
const department = String(row[M.department] ?? '').trim() || null;
if (!department) ctx.warnings.push('No department code in Vendor_Account_Map');

// 3. Location: the account map is authoritative for non-PO bills; the document must not disagree
const mapCode = up(row[M.code]);
const locRow = locRows.find(r => up(r[LC.code]) === mapCode || String(r[LC.aliases] ?? '').toUpperCase().split(/[\s,;|\/]+/).includes(mapCode));
if (!locRow) return exc('LOCATION_NOT_IN_MASTER', `Account map location ${mapCode || '(blank)'} is not in Location_Master`);
const code = up(locRow[LC.code]);
const prev = ctx.location || {};
if (prev.status === 'RESOLVED' && up(prev.code) !== code)
  return exc('LOCATION_CONFLICT', `Account map says ${code}; the document points to ${prev.code} (${prev.method})`);
const entity = String(locRow[LC.entity] ?? '').trim() || null;
if (!entity) return exc('LOCATION_NOT_IN_MASTER', `Location ${code} has no Sage entity in Location_Master`);
if (row[M.entity] && lc(row[M.entity]) !== lc(entity)) ctx.warnings.push(`Vendor_Account_Map entity "${row[M.entity]}" differs from Location_Master "${entity}"; using Location_Master`);
ctx.location = { status: 'RESOLVED', code, entity_id: entity,
  sage_location_id: String(locRow[LC.sageLocation] ?? '').trim() || entity,
  name: locRow[LC.name] ?? entity, st_tenant_id: locRow[LC.tenant] ? String(locRow[LC.tenant]) : null,
  active: locRow[LC.active] === true, needs_review: false,
  method: prev.status === 'RESOLVED' ? `${prev.method}+ACCOUNT_MAP` : 'ACCOUNT_MAP',
  method_detail: (prev.status === 'RESOLVED' && prev.method_detail ? prev.method_detail + '; ' : '') + `Vendor Account Map (account ${row[M.account]}) = ${code}` };
if (!ctx.location.active) return exc('LOCATION_NOT_ACTIVE', `Location ${code} (${entity}) is not active yet in Location_Master`);

// 4. Amount: current-period charges when printed, so an unpaid previous balance is not posted twice
const useCurrent = CONFIG.AMOUNT_BASIS === 'current_charges' && inv.current_charges !== null && inv.current_charges !== undefined;
const amount = useCurrent ? inv.current_charges : inv.invoice_total;
if (amount === null || amount === undefined || !Number.isFinite(Number(amount))) return exc('AMOUNT_MISSING', 'No invoice total or current charges could be read');
if (Number(amount) <= 0) return exc('CREDIT_MEMO_REVIEW', `Amount to post is ${amount}; credits and zero bills are not auto-posted`);
const due = inv.amount_due ?? inv.invoice_total;
if (useCurrent && due !== null && due !== undefined && Number(due) - Number(amount) > CONFIG.TOL)
  ctx.warnings.push(`Posting current charges ${amount}; amount due ${due} includes ${round2(due - amount)} carried forward`);

ctx.account_match = { result: 'PASS', detail: `account ${acct || '(by vendor)'} -> ${row[M.vendor]} / GL ${gl} / ${code}` };
ctx.gl = { account: gl, name: glRaw };
const kind = ctx.lane === 'INDIRECT_ADVERTISING' ? 'Advertising' : ctx.lane === 'INDIRECT_UTILITY' ? 'Utility' : 'Expense';
ctx.status = 'READY_TO_POST';
ctx.payload = {
  location_id: ctx.location.entity_id,
  line_location_id: ctx.location.sage_location_id,
  vendor: { sage_vendor_id: String(row[M.sageVendor] ?? '').trim() || null, name: ctx.vendor?.name || row[M.vendor], location_code: code },
  bill: { record_id: inv.invoice_number, doc_number: inv.account_number || null,
          when_created: inv.invoice_date, when_due: inv.due_date, term: inv.payment_terms,
          description: `${ctx.vendor?.name || row[M.vendor]} ${inv.invoice_number}${inv.charge_summary ? ' - ' + inv.charge_summary : ''}` },
  lines: [{ amount: round2(Number(amount)), gl_account: gl, gl_name: glRaw, item_names: [], department,
            memo: `${kind} ${inv.invoice_number}${inv.account_number ? ' / acct ' + inv.account_number : ''}` }],
};
if (!ctx.payload.vendor.sage_vendor_id) ctx.warnings.push('No Sage vendor ID in Vendor_Account_Map; Sage Post will match the vendor by name');
return [{ json: ctx }];
